    def get_requirement_table(self, doc_type: str = None) -> str:
        """Generate markdown table of requirements"""
        requirements = self.requirements_db.get("requirements", [])

        if doc_type:
            requirements = [r for r in requirements if r.get("type") == doc_type]

        lines = [
            "| ID | 类型 | 描述 | 优先级 | eSig | 状态 |",
            "|----|------|------|--------|------|------|",
        ]

        for r in requirements:
            esig = "是" if r.get("esig_required") else "否"
            lines.append(
                f"| {r.get('id')} | {r.get('type')} | "
                f"{r.get('description', '')[:50]}... | "
                f"{r.get('priority')} | {esig} | "
                f"{r.get('status')} |"
            )

        return "\n".join(lines)

    def get_risk_table(self) -> str:
        """Generate markdown table of risks"""
        risks = self.requirements_db.get("risks", [])

        lines = [
            "| ID | 风险描述 | 严重性 | 可能性 | 可检测性 | RPN | 等级 | 状态 |",
            "|----|----------|--------|--------|----------|-----|------|------|",
        ]

        for r in risks:
            lines.append(
                f"| {r.get('id')} | {r.get('risk_description', '')[:40]}... | "
                f"{r.get('severity')} | {r.get('likelihood')} | {r.get('detectability')} | "
                f"{r.get('rpn')} | {r.get('risk_level')} | {r.get('status')} |"
            )

        return "\n".join(lines)

    def get_test_results_table(self, test_type: str = None) -> str:
        """Generate markdown table of test results"""
        test_results = self.requirements_db.get("test_results", [])

        if test_type:
            test_results = [t for t in test_results if t.get("test_type") == test_type]

        lines = [
            "| 测试ID | 测试名称 | 类型 | 状态 | 执行时间 |",
            "|--------|----------|------|------|----------|",
        ]

        for t in test_results:
            duration = f"{t.get('duration', 0):.2f}s" if t.get("duration") else "N/A"
            lines.append(
                f"| {t.get('test_id')} | {t.get('test_name', '')[:30]}... | "
                f"{t.get('test_type')} | {t.get('status')} | {duration} |"
            )

        return "\n".join(lines)

    def get_summary_statistics(self) -> Dict[str, Any]:
        """Get summary statistics for documents"""
        requirements = self.requirements_db.get("requirements", [])
        risks = self.requirements_db.get("risks", [])
        test_results = self.requirements_db.get("test_results", [])

        return {
            "requirements": {
                "total": len(requirements),
                "by_type": self._count_by(requirements, "type"),
                "by_priority": self._count_by(requirements, "priority"),
                "by_status": self._count_by(requirements, "status"),
                "esig_count": len([r for r in requirements if r.get("esig_required")]),
            },
            "risks": {
                "total": len(risks),
                "by_level": self._count_by(risks, "risk_level"),
                "by_status": self._count_by(risks, "status"),
            },
            "tests": {
                "total": len(test_results),
                "by_type": self._count_by(test_results, "test_type"),
                "by_status": self._count_by(test_results, "status"),
            },
        }

    def _count_by(self, items: list, key: str) -> Dict[str, int]:
        """Count items by a specific key"""
        counts = {}
        for item in items:
            value = item.get(key, "unknown")
            counts[value] = counts.get(value, 0) + 1
        return counts

    def validate_completeness(self, doc_type: str) -> Dict[str, Any]:
        """Check document completeness"""
        requirements = self.requirements_db.get("requirements", [])
        test_results = self.requirements_db.get("test_results", [])

        issues = []
        warnings = []

        # Check if requirements exist
        if len(requirements) == 0:
            issues.append("没有需求数据，请先添加或解析需求")

        # Check if requirements are linked to tests
        req_ids = {r.get("id") for r in requirements}
        tested_req_ids = {
            t.get("requirement_id") for t in test_results if t.get("requirement_id")
        }

        untested = req_ids - tested_req_ids
        if untested:
            warnings.append(f"以下需求未关联测试: {', '.join(list(untested)[:5])}")

        # Check risk assessment
        risks = self.requirements_db.get("risks", [])
        if len(risks) == 0 and len(requirements) > 0:
            warnings.append("没有风险评估数据，请运行风险分析")

        return {"complete": len(issues) == 0, "issues": issues, "warnings": warnings}

"""Git Linker module for CSV Documentation Generator

Links requirements to commits for traceability.
"""

import re
import subprocess
import json
from pathlib import Path
from typing import List, Dict, Any, Optional
from dataclasses import dataclass, asdict
from datetime import datetime


@dataclass
class CommitLink:
    """Represents a link between a commit and requirements"""

    commit_hash: str
    commit_message: str
    requirements: List[str]
    linked_at: str
    author: Optional[str] = None


class GitLinker:
    """Link requirements to git commits"""

    # Pattern to extract requirement IDs from commit messages
    REQUIREMENT_PATTERN = (
        r"\b(URS-\d{3}|FS-\d{3}|TS-\d{3}|IQ-\d{3}|OQ-\d{3}|PQ-\d{3}|RA-\d{3})\b"
    )

    def __init__(self, project_path: Optional[Path] = None):
        self.project_path = project_path or Path.cwd()
        self.requirements_db = self._load_requirements_db()

    def _load_requirements_db(self) -> Dict[str, Any]:
        """Load requirements database"""
        db_path = self.project_path / "requirements.json"
        if db_path.exists():
            with open(db_path, "r", encoding="utf-8") as f:
                return json.load(f)
        return {"commit_links": []}

    def _save_commit_links(self):
        """Save commit links to database"""
        db_path = self.project_path / "requirements.json"
        with open(db_path, "w", encoding="utf-8") as f:
            json.dump(self.requirements_db, f, indent=2, ensure_ascii=False)

    def _get_commit_info(self, commit_hash: str) -> Dict[str, Any]:
        """Get commit information"""
        try:
            result = subprocess.run(
                ["git", "show", commit_hash, "--format=%H%n%an%n%ae%n%B", "-s"],
                capture_output=True,
                text=True,
                cwd=self.project_path,
            )
            if result.returncode == 0:
                lines = result.stdout.strip().split("\n")
                return {
                    "hash": lines[0] if len(lines) > 0 else commit_hash,
                    "author": lines[1] if len(lines) > 1 else None,
                    "email": lines[2] if len(lines) > 2 else None,
                    "message": lines[3] if len(lines) > 3 else "",
                }
        except Exception:
            pass

        return {"hash": commit_hash, "author": None, "email": None, "message": ""}

    def extract_requirements_from_message(self, message: str) -> List[str]:
        """Extract requirement IDs from a commit message"""
        matches = re.findall(self.REQUIREMENT_PATTERN, message, re.IGNORECASE)
        return list(set(matches))  # Remove duplicates

    def link_commit(
        self, commit_hash: str, requirements: List[str] = None
    ) -> CommitLink:
        """Link a commit to requirements

        If requirements is None, extracts from commit message.
        """
        commit_info = self._get_commit_info(commit_hash)

        if not requirements:
            requirements = self.extract_requirements_from_message(
                commit_info["message"]
            )

        link = CommitLink(
            commit_hash=commit_info["hash"],
            commit_message=commit_info["message"].split("\n")[0],  # First line only
            requirements=requirements,
            linked_at=datetime.now().isoformat(),
            author=commit_info["author"],
        )

        self.requirements_db.setdefault("commit_links", []).append(asdict(link))
        self._save_commit_links()

        return link

    def unlink_commit(self, commit_hash: str) -> bool:
        """Remove link for a commit"""
        links = self.requirements_db.get("commit_links", [])
        initial_len = len(links)
        self.requirements_db["commit_links"] = [
            link for link in links if link.get("commit_hash") != commit_hash
        ]

        if len(self.requirements_db["commit_links"]) < initial_len:
            self._save_commit_links()
            return True
        return False

    def get_links_for_requirement(self, requirement_id: str) -> List[CommitLink]:
        """Get all commits linked to a requirement"""
        links = []
        for link_data in self.requirements_db.get("commit_links", []):
            if requirement_id in link_data.get("requirements", []):
                links.append(CommitLink(**link_data))
        return links

    def get_links_for_commit(self, commit_hash: str) -> Optional[CommitLink]:
        """Get links for a specific commit"""
        for link_data in self.requirements_db.get("commit_links", []):
            if link_data.get("commit_hash") == commit_hash:
                return CommitLink(**link_data)
        return None

    def get_all_links(self) -> List[CommitLink]:
        """Get all commit links"""
        return [
            CommitLink(**link_data)
            for link_data in self.requirements_db.get("commit_links", [])
        ]

    def link_last_commit(self, requirements: List[str] = None) -> Optional[CommitLink]:
        """Link the last git commit"""
        try:
            result = subprocess.run(
                ["git", "rev-parse", "HEAD"],
                capture_output=True,
                text=True,
                cwd=self.project_path,
            )
            if result.returncode == 0:
                commit_hash = result.stdout.strip()
                return self.link_commit(commit_hash, requirements)
        except Exception:
            pass
        return None

    def get_recent_commits(self, count: int = 10) -> List[Dict[str, Any]]:
        """Get recent commits with their linked requirements"""
        try:
            result = subprocess.run(
                ["git", "log", f"-{count}", "--format=%H%n%s"],
                capture_output=True,
                text=True,
                cwd=self.project_path,
            )
            if result.returncode == 0:
                commits = []
                lines = result.stdout.strip().split("\n")
                for i in range(0, len(lines) - 1, 2):
                    if i + 1 < len(lines):
                        commit_hash = lines[i]
                        message = lines[i + 1]
                        reqs = self.extract_requirements_from_message(message)
                        commits.append(
                            {
                                "hash": commit_hash,
                                "message": message,
                                "requirements": reqs,
                                "linked": reqs
                                in [
                                    link.get("requirements")
                                    for link in self.requirements_db.get(
                                        "commit_links", []
                                    )
                                ],
                            }
                        )
                return commits
        except Exception:
            pass
        return []

    def get_traceability_matrix(self) -> List[Dict[str, Any]]:
        """Get requirement-to-commit traceability matrix"""
        matrix = []

        for req in self.requirements_db.get("requirements", []):
            req_id = req.get("id")
            links = self.get_links_for_requirement(req_id)

            matrix.append(
                {
                    "requirement_id": req_id,
                    "requirement_type": req.get("type"),
                    "requirement_description": req.get("description", "")[:50],
                    "priority": req.get("priority"),
                    "status": req.get("status"),
                    "commits": [
                        {"hash": link.commit_hash[:8], "message": link.commit_message}
                        for link in links
                    ],
                    "commit_count": len(links),
                }
            )

        return matrix

"""Template versioning module for CSV Documentation Generator

Handles template version tracking and compatibility checking.
"""

import json
import re
from pathlib import Path
from typing import Dict, Any, Optional, Tuple
from dataclasses import dataclass


TEMPLATE_VERSION = "1.2.0"

COMPATIBILITY_RULES = {
    "1.0.0": {"min_generator": "1.0.0", "breaking": []},
    "1.1.0": {"min_generator": "1.1.0", "breaking": []},
    "1.2.0": {"min_generator": "1.2.0", "breaking": []},
}


@dataclass
class VersionInfo:
    major: int
    minor: int
    patch: int

    @classmethod
    def from_string(cls, version: str) -> "VersionInfo":
        parts = version.split(".")
        return cls(
            major=int(parts[0]) if len(parts) > 0 else 0,
            minor=int(parts[1]) if len(parts) > 1 else 0,
            patch=int(parts[2]) if len(parts) > 2 else 0,
        )

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

    def __ge__(self, other: "VersionInfo") -> bool:
        return (self.major, self.minor, self.patch) >= (
            other.major,
            other.minor,
            other.patch,
        )

    def __lt__(self, other: "VersionInfo") -> bool:
        return (self.major, self.minor, self.patch) < (
            other.major,
            other.minor,
            other.patch,
        )


@dataclass
class CompatibilityResult:
    compatible: bool
    current_version: str
    required_version: Optional[str]
    message: str


def get_template_version(db: Dict[str, Any]) -> Optional[str]:
    """Get template version from requirements database"""
    return db.get("template_version") or db.get("version")


def set_template_version(db: Dict[str, Any], version: str) -> Dict[str, Any]:
    """Set template version in requirements database"""
    db["template_version"] = version
    return db


def check_template_compatibility(
    db: Dict[str, Any], generator_version: str = TEMPLATE_VERSION
) -> CompatibilityResult:
    """Check if template version is compatible with generator

    Args:
        db: Requirements database
        generator_version: Current generator version

    Returns:
        CompatibilityResult with compatibility status and message
    """
    template_version = get_template_version(db)

    if not template_version:
        return CompatibilityResult(
            compatible=True,
            current_version=generator_version,
            required_version=None,
            message="No template version specified, assuming compatible",
        )

    template_v = VersionInfo.from_string(template_version)
    generator_v = VersionInfo.from_string(generator_version)

    if template_v > generator_v:
        return CompatibilityResult(
            compatible=False,
            current_version=generator_version,
            required_version=template_version,
            message=f"Template version {template_version} requires generator >= {template_version}. Current: {generator_version}",
        )

    for rule_version, rule in COMPATIBILITY_RULES.items():
        rule_v = VersionInfo.from_string(rule_version)
        if template_v >= rule_v:
            min_gen = VersionInfo.from_string(rule["min_generator"])
            if generator_v < min_gen:
                return CompatibilityResult(
                    compatible=False,
                    current_version=generator_version,
                    required_version=rule["min_generator"],
                    message=f"Template {template_version} requires generator >= {rule['min_generator']}. Current: {generator_version}",
                )

    return CompatibilityResult(
        compatible=True,
        current_version=generator_version,
        required_version=None,
        message=f"Template {template_version} is compatible with generator {generator_version}",
    )


def detect_template_version_from_file(file_path: Path) -> Optional[str]:
    """Detect template version from a template file

    Looks for version markers like:
    - <!-- template-version: 1.2.0 -->
    - {% set template_version = "1.2.0" %}
    - Version: 1.2.0 (in first 10 lines)
    """
    if not file_path.exists():
        return None

    try:
        with open(file_path, "r", encoding="utf-8") as f:
            lines = [f.readline() for _ in range(10)]

        content = "".join(lines)

        patterns = [
            r"template-version:\s*(\d+\.\d+\.\d+)",
            r'template_version\s*=\s*["\'](\d+\.\d+\.\d+)["\']',
            r"version:\s*(\d+\.\d+\.\d+)",
        ]

        for pattern in patterns:
            match = re.search(pattern, content)
            if match:
                return match.group(1)

    except Exception:
        pass

    return None


def migrate_template_if_needed(
    db: Dict[str, Any], target_version: str = TEMPLATE_VERSION
) -> Tuple[Dict[str, Any], bool]:
    """Migrate template data to current version if needed

    Returns:
        Tuple of (updated_db, was_migrated)
    """
    current_version = get_template_version(db)

    if not current_version:
        db = set_template_version(db, target_version)
        return db, True

    if current_version == target_version:
        return db, False

    migrated = False

    if VersionInfo.from_string(current_version) < VersionInfo.from_string("1.1.0"):
        if "gamp_category" not in db:
            db["gamp_category"] = None
        migrated = True

    if VersionInfo.from_string(current_version) < VersionInfo.from_string("1.2.0"):
        for req in db.get("requirements", []):
            if "risk_level" not in req:
                req["risk_level"] = None
        migrated = True

    db = set_template_version(db, target_version)
    return db, migrated


def load_requirements_with_version(
    path: Path,
) -> Tuple[Dict[str, Any], CompatibilityResult]:
    """Load requirements.json and check compatibility

    Returns:
        Tuple of (db, compatibility_result)
    """
    try:
        with open(path, "r", encoding="utf-8") as f:
            db = json.load(f)

        compatibility = check_template_compatibility(db)
        return db, compatibility

    except json.JSONDecodeError as e:
        return {}, CompatibilityResult(
            compatible=False,
            current_version=TEMPLATE_VERSION,
            required_version=None,
            message=f"Failed to parse requirements.json: {e}",
        )
    except Exception as e:
        return {}, CompatibilityResult(
            compatible=False,
            current_version=TEMPLATE_VERSION,
            required_version=None,
            message=f"Failed to load requirements.json: {e}",
        )

"""Standards Reader for AI Agent Code Annotation Standards

This module provides a unified interface to read the Central Standards Registry
(standards/code-annotations.json) for code annotation conventions.

Skill-agnostic: can be used by any skill without coupling.
Uses {baseDir} relative path to locate standards file within skill directory.
"""

import json
import os
from pathlib import Path
from typing import Dict, List, Optional, Any


class StandardsReader:
    """
    Reads and provides access to the Central Standards Registry.

    The standards file is located at:
        {skill_root}/standards/code-annotations.json

    If the file doesn't exist, built-in defaults are used.
    """

    def __init__(self, standards_path: Optional[str] = None):
        """
        Initialize StandardsReader.

        Args:
            standards_path: Optional custom path to standards file.
                          Defaults to {skill_root}/standards/code-annotations.json
        """
        if standards_path:
            self.standards_path = Path(standards_path)
        else:
            self.standards_path = self._get_default_standards_path()
        self._standards = None
        self._loaded = False

    def _get_default_standards_path(self) -> Path:
        """
        Get the default standards path within the skill directory.
        Uses Path(__file__).parent.parent to locate skill root.
        """
        skill_root = Path(__file__).parent.parent
        return skill_root / "standards" / "code-annotations.json"

    @property
    def standards(self) -> Dict[str, Any]:
        """Lazy load standards from file."""
        if not self._loaded:
            self._load()
        return self._standards or {}

    def _load(self) -> None:
        """Load standards from file, using defaults if not found."""
        self._loaded = True

        if self.standards_path.exists():
            try:
                with open(self.standards_path, "r", encoding="utf-8") as f:
                    self._standards = json.load(f)
            except (json.JSONDecodeError, IOError) as e:
                print(
                    f"Warning: Failed to load standards from {self.standards_path}: {e}"
                )
                self._standards = self._get_defaults()
        else:
            print(f"Info: Standards file not found at {self.standards_path}")
            print(f"      Using built-in defaults.")
            self._standards = self._get_defaults()

    def _get_defaults(self) -> Dict[str, Any]:
        """Return built-in default standards."""
        return {
            "version": "1.0",
            "description": "Built-in defaults (standards file not found)",
            "standards": {
                "requirement_markers": {
                    "enabled": True,
                    "patterns": [
                        {"style": "python", "pattern": "# @REQ {id} - {description}"},
                        {"style": "cpp", "pattern": "// @REQ {id} - {description}"},
                    ],
                },
                "test_markers": {
                    "enabled": True,
                    "patterns": [
                        {
                            "style": "python",
                            "pattern": "# @TEST[{type-id}] - {description}",
                        },
                        {
                            "style": "cpp",
                            "pattern": "// @TEST[{type-id}] - {description}",
                        },
                    ],
                },
                "risk_markers": {
                    "enabled": True,
                    "pattern": "// @RISK [{H|M|L}]",
                    "levels": {
                        "H": {"name": "High Risk"},
                        "M": {"name": "Medium Risk"},
                        "L": {"name": "Low Risk"},
                    },
                },
                "modules": {},
            },
            "configurable": True,
            "enforcement": "advisory",
        }

    def is_enabled(self, marker_type: str) -> bool:
        """
        Check if a marker type is enabled.

        Args:
            marker_type: One of 'requirement_markers', 'test_markers',
                        'design_markers', 'risk_markers'

        Returns:
            True if enabled, False otherwise
        """
        standards = self.standards.get("standards", {})
        marker = standards.get(marker_type, {})
        return marker.get("enabled", False)

    def get_requirement_patterns(self) -> List[Dict[str, str]]:
        """Get all requirement marker patterns."""
        if not self.is_enabled("requirement_markers"):
            return []

        standards = self.standards.get("standards", {})
        patterns = standards.get("requirement_markers", {}).get("patterns", [])
        return patterns

    def get_test_patterns(self) -> List[Dict[str, str]]:
        """Get all test marker patterns."""
        if not self.is_enabled("test_markers"):
            return []

        standards = self.standards.get("standards", {})
        patterns = standards.get("test_markers", {}).get("patterns", [])
        return patterns

    def get_design_patterns(self) -> List[Dict[str, str]]:
        """Get all design specification marker patterns (FS, TS)."""
        if not self.is_enabled("design_markers"):
            return []

        standards = self.standards.get("standards", {})
        patterns = standards.get("design_markers", {}).get("patterns", [])
        return patterns

    def get_risk_pattern(self) -> str:
        """Get the risk marker pattern."""
        if not self.is_enabled("risk_markers"):
            return ""

        standards = self.standards.get("standards", {})
        return standards.get("risk_markers", {}).get("pattern", "// @RISK [H/M/L]")

    def get_risk_levels(self) -> Dict[str, Dict[str, str]]:
        """Get risk level definitions."""
        if not self.is_enabled("risk_markers"):
            return {}

        standards = self.standards.get("standards", {})
        return standards.get("risk_markers", {}).get("levels", {})

    def get_modules(self) -> Dict[str, Dict[str, str]]:
        """Get module definitions."""
        standards = self.standards.get("standards", {})
        return standards.get("modules", {})

    def get_module_info(self, module_id: str) -> Optional[Dict[str, str]]:
        """Get information about a specific module."""
        modules = self.get_modules()
        return modules.get(module_id)

    def get_test_prefix(self, module_id: str) -> str:
        """Get the test prefix for a module."""
        module = self.get_module_info(module_id)
        if module:
            return module.get("test_prefix", module_id.upper()[:2])
        return module_id.upper()[:2]

    def should_enforce(self) -> bool:
        """Check if standards should be strictly enforced."""
        return self.standards.get("enforcement", "advisory") == "strict"

    def is_configurable(self) -> bool:
        """Check if standards are configurable."""
        return self.standards.get("configurable", True)

    def get_version(self) -> str:
        """Get the standards version."""
        return self.standards.get("version", "unknown")

    def get_purpose(self) -> str:
        """Get the purpose description."""
        return self.standards.get("purpose", "")

    def get_style_pattern(self, marker_type: str, style: str) -> Optional[str]:
        """
        Get pattern for a specific marker type and code style.

        Args:
            marker_type: One of 'requirement_markers', 'test_markers', 'design_markers'
            style: Code style (e.g., 'python', 'cpp', 'javascript')

        Returns:
            Pattern string or None if not found
        """
        if marker_type == "requirement_markers":
            patterns = self.get_requirement_patterns()
        elif marker_type == "test_markers":
            patterns = self.get_test_patterns()
        elif marker_type == "design_markers":
            patterns = self.get_design_patterns()
        else:
            return None

        for p in patterns:
            if p.get("style") == style:
                return p.get("pattern")
        return None

    def format_requirement_marker(
        self, req_id: str, description: str, style: str = "python"
    ) -> str:
        """
        Format a requirement marker string.

        Args:
            req_id: Requirement ID (e.g., 'URS-001')
            description: Requirement description
            style: Code style (default: 'python')

        Returns:
            Formatted marker string
        """
        pattern = self.get_style_pattern("requirement_markers", style)
        if not pattern:
            pattern = "# @REQ {id} - {description}"

        return pattern.replace("{id}", req_id).replace("{description}", description)

    def format_test_marker(
        self, test_id: str, description: str, style: str = "python"
    ) -> str:
        """
        Format a test marker string.

        Args:
            test_id: Test case ID (e.g., 'OQ-UM-001')
            description: Test description
            style: Code style (default: 'python')

        Returns:
            Formatted marker string
        """
        pattern = self.get_style_pattern("test_markers", style)
        if not pattern:
            pattern = "# @TEST[{type-id}] - {description}"

        return pattern.replace("{type-id}", test_id).replace(
            "{description}", description
        )

    def format_risk_marker(self, level: str) -> str:
        """
        Format a risk marker string.

        Args:
            level: Risk level ('H', 'M', or 'L')

        Returns:
            Formatted marker string
        """
        pattern = self.get_risk_pattern()
        return pattern.replace("{H|M|L}", level)

    def get_required_for_skills(self) -> List[str]:
        """Get list of skills that require these standards."""
        standards = self.standards.get("standards", {})
        req_markers = standards.get("requirement_markers", {})
        return req_markers.get("required_for_skills", [])

    def to_dict(self) -> Dict[str, Any]:
        """Return the full standards dictionary."""
        return self.standards.copy()

    def get_system_prompt_rules(self) -> str:
        """
        Get the standards formatted as rules text for system prompt.

        Returns:
            Multi-line string suitable for adding to system prompt
        """
        rules = [
            "Code Annotation Rules (for GxP traceability):",
            "- When writing code that implements requirements, add @REQ markers: # @REQ URS-xxx - description",
            "- When writing test cases, add @TEST markers: # @TEST[OQ-UM-xxx] - description",
            "- Mark high-risk code sections with @RISK H (security, compliance, audit trail related)",
            "- Mark medium-risk code with @RISK M",
            "- Mark low-risk code with @RISK L",
        ]
        return "\n".join(rules)


